class Rng:
    __slots__ = ("state",)

    def __init__(self, seed):
        self.state = (seed & 0xFFFFFFFFFFFFFFFF) or 0x9E3779B97F4A7C15

    def nxt(self):
        x = self.state
        x ^= (x >> 12)
        x ^= (x << 25) & 0xFFFFFFFFFFFFFFFF
        x ^= (x >> 27)
        self.state = x
        return (x * 0x2545F4914F6CDD1D) & 0xFFFFFFFFFFFFFFFF

    def randint(self, lo, hi):
        return lo + self.nxt() % (hi - lo + 1)

    def chance(self, num, den):
        return self.nxt() % den < num

    def choice(self, seq):
        return seq[self.nxt() % len(seq)]

    def shuffle(self, items):
        for i in range(len(items) - 1, 0, -1):
            j = self.nxt() % (i + 1)
            items[i], items[j] = items[j], items[i]


def to_min(text):
    d = date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    return (d - EPOCH).days * 1440 + int(text[11:13]) * 60 + int(text[14:16])


def to_iso(minute):
    d, r = divmod(minute, 1440)
    return f"{(EPOCH + timedelta(days=d)).isoformat()}T{r // 60:02d}:{r % 60:02d}"


def day_iso(day):
    return (EPOCH + timedelta(days=day)).isoformat()


def day_index(text):
    return (date.fromisoformat(text) - EPOCH).days


def site_number(site_id):
    return int(site_id[1:])


def entry_number(entry_id):
    return int(entry_id[1:])


def canon_channel(label):
    return label.strip().upper()


def decimal_parts(text):
    text = text.strip()
    if "." in text:
        whole, frac = text.split(".", 1)
    else:
        whole, frac = text, ""
    return int(whole + frac), 10 ** len(frac)


def half_up_product(raw, factor_text):
    num, den = decimal_parts(factor_text)
    return (2 * raw * num + den) // (2 * den)


def tenths(text):
    num, den = decimal_parts(text)
    return num * 10 // den


def dump(obj):
    return json.dumps(obj, sort_keys=True, indent=2) + "\n"


# ---------------------------------------------------------------- reference


def _read_csv(path):
    with path.open(encoding="utf-8-sig", newline="") as fh:
        return list(csv.DictReader(fh))


def _read_json(path):
    return json.loads(path.read_text(encoding="utf-8-sig"))


def load_extract(root):
    root = Path(root)
    manifest = _read_json(root / "extract_manifest.json")
    policy = None
    for path in sorted(root.glob("network_policy*.json")):
        candidate = _read_json(path)
        if candidate.get("revision") == manifest["policy_revision"]:
            policy = candidate
    register = None
    for path in sorted(root.glob("span_register*.csv")):
        rows = _read_csv(path)
        if rows and rows[0]["revision"] == manifest["span_register_revision"]:
            register = rows
    return {
        "manifest": manifest,
        "policy": policy,
        "zone": _read_json(root / "zone_rules.json"),
        "sites": _read_csv(root / "site_register.csv"),
        "deployments": _read_csv(root / "unit_deployments.csv"),
        "tags": _read_csv(root / "asset_tags.csv"),
        "cards": _read_csv(root / "card_readings.csv"),
        "journal": _read_csv(root / "receipt_journal.csv"),
        "maintenance": _read_json(root / "maintenance_log.json"),
        "register": register,
    }


def civil_to_utc(civil, zone):
    std = zone["standard_offset_minutes"]
    for period in zone["daylight_saving"]:
        begins = to_min(period["begins"]) - std
        ends = to_min(period["ends"]) - std - period["shift_minutes"]
        candidate = civil - std - period["shift_minutes"]
        if begins <= candidate < ends:
            return candidate
    return civil - std


def span_table(register, tags):
    """unit -> sorted list of (effective, entry_no, factor_text) for live set entries."""
    tag_rows = [(t["asset_tag"], t["unit_id"], to_min(t["valid_from_utc"]),
                 to_min(t["valid_to_utc"]) if t["valid_to_utc"] else None) for t in tags]
    by_id = {r["entry_id"]: r for r in register}
    void = set()
    for r in register:
        if r["action"] == "withdraw" and r["target_entry"] in by_id:
            if by_id[r["target_entry"]]["action"] in ("set", "amend"):
                void.add(r["target_entry"])
    amended = {}
    for r in sorted(register, key=lambda x: entry_number(x["entry_id"])):
        if r["action"] != "amend" or r["entry_id"] in void:
            continue
        target = by_id.get(r["target_entry"])
        if target is None or target["action"] != "set":
            continue
        amended[r["target_entry"]] = r["span_factor"]
    table = {}
    for r in register:
        if r["action"] != "set" or r["entry_id"] in void:
            continue
        eff = to_min(r["effective_utc"])
        unit = None
        ref = r["unit_ref"]
        for tag, owner, start, end in tag_rows:
            if tag == ref and start <= eff and (end is None or eff < end):
                unit = owner
        if unit is None and not any(tag == ref for tag, _, _, _ in tag_rows):
            unit = ref
        if unit is None:
            continue
        factor = amended.get(r["entry_id"], r["span_factor"])
        table.setdefault(unit, []).append((eff, entry_number(r["entry_id"]), factor))
    for rows in table.values():
        rows.sort()
    return table


def factor_at(table, unit, instant):
    best = None
    for eff, num, factor in table.get(unit, ()):
        if eff <= instant:
            best = factor
        else:
            break
    return best


def recover_constant_offsets(ex):
    """Fixed per-unit offsets from (channel, frame) receipts; enough for an extract whose clocks never step."""
    channel_of = {d["unit_id"]: canon_channel(d["channel"]) for d in ex["deployments"]}
    heard = {(canon_channel(j["channel"]), to_min(j["received_utc"])): int(j["frame"]) for j in ex["journal"]}
    offsets = {}
    for unit in sorted({c["unit_id"] for c in ex["cards"]}):
        votes = {}
        for c in ex["cards"]:
            if c["unit_id"] != unit:
                continue
            stamp = to_min(c["card_stamp"])
            for o in range(-MAX_OFFSET, MAX_OFFSET + 1):
                if heard.get((channel_of[unit], stamp - o)) == int(c["frame"]):
                    votes[o] = votes.get(o, 0) + 1
        offsets[unit] = [(0, max(sorted(votes), key=lambda o: votes[o]))]
    return offsets


def reference_reports(root, offsets=None):
    ex = load_extract(root)
    if offsets is None:
        offsets = recover_constant_offsets(ex)
    man, pol, zone = ex["manifest"], ex["policy"], ex["zone"]
    std = zone["standard_offset_minutes"]
    standard = tenths(pol["daily_standard"])
    hour_min, day_min = int(pol["hour_min_readings"]), int(pol["day_min_hours"])
    first = day_index(man["first_day"])
    days = int(man["days"])
    required = math.ceil(days * int(pol["site_min_valid_day_percent"]) / 100)
    sites = {s["site_id"]: s for s in ex["sites"]}
    site_order = sorted(sites, key=site_number)
    deployments = {}
    channel_of = {}
    for d in ex["deployments"]:
        deployments.setdefault(d["unit_id"], []).append(
            (to_min(d["installed_utc"]), to_min(d["removed_utc"]) if d["removed_utc"] else None, d["site_id"]))
        channel_of[d["unit_id"]] = canon_channel(d["channel"])
    windows = {}
    for m in ex["maintenance"]["entries"]:
        if ex["maintenance"]["time_basis"] == "civil":
            begins, ends = civil_to_utc(to_min(m["begins"]), zone), civil_to_utc(to_min(m["ends"]), zone)
        else:
            begins, ends = to_min(m["begins"]), to_min(m["ends"])
        windows.setdefault(m["site_id"], []).append((begins, ends))
    spans = span_table(ex["register"], ex["tags"])
    heard = {(canon_channel(j["channel"]), to_min(j["received_utc"])): int(j["frame"]) for j in ex["journal"]}

    by_unit = {}
    for c in ex["cards"]:
        by_unit.setdefault(c["unit_id"], []).append(c)
    reasons = {k: 0 for k in ("outside_window", "undeployed", "missing_value", "flagged", "uncalibrated", "maintenance")}
    excluded = valid = 0
    hourly = {}
    site_valid = {s: 0 for s in sites}
    unit_rows = []
    for unit in sorted(by_unit):
        rows = sorted(by_unit[unit], key=lambda c: to_min(c["card_stamp"]))
        segs = offsets[unit]
        received = 0
        last_offset = None
        for k, c in enumerate(rows):
            o = [off for start, off in segs if start <= k][-1]
            last_offset = o
            stamp = to_min(c["card_stamp"])
            t = stamp - o
            if heard.get((channel_of.get(unit), t)) == int(c["frame"]):
                received += 1
            hour = (t + std - 1) // 60
            day = hour // 24
            if not first <= day < first + days:
                reasons["outside_window"] += 1
                excluded += 1
                continue
            site = None
            for inst, rem, s in deployments.get(unit, ()):
                if inst <= t and (rem is None or t < rem):
                    site = s
            bad = False
            if site is None:
                reasons["undeployed"] += 1
                bad = True
            if c["pm25_raw"] == "":
                reasons["missing_value"] += 1
                bad = True
            if c["status"] != "":
                reasons["flagged"] += 1
                bad = True
            factor = factor_at(spans, unit, t)
            if factor is None:
                reasons["uncalibrated"] += 1
                bad = True
            if site is not None and any(b <= t < e for b, e in windows.get(site, ())):
                reasons["maintenance"] += 1
                bad = True
            if bad:
                excluded += 1
                continue
            valid += 1
            site_valid[site] += 1
            value = half_up_product(int(c["pm25_raw"]), factor)
            cell = hourly.setdefault((site, hour), [0, 0])
            cell[0] += value
            cell[1] += 1
        unit_rows.append({"unit_id": unit, "channel": channel_of.get(unit),
                          "card_rows": len(rows), "received_packets": received})

    daily_hours = {}
    valid_hours = 0
    for (site, hour), (total, count) in hourly.items():
        if count >= hour_min:
            valid_hours += 1
            cell = daily_hours.setdefault((site, hour // 24), [0, 0])
            cell[0] += total // count
            cell[1] += 1
    daily = {s: {} for s in sites}
    complete = {s: 0 for s in sites}
    for (site, day), (total, count) in daily_hours.items():
        mean = total // count
        if count >= day_min:
            daily[site][day] = mean
            complete[site] += 1
        elif mean > standard:
            daily[site][day] = mean

    audit_sites = []
    per_site = {}
    for s in site_order:
        values = sorted(daily[s].values(), reverse=True)
        n = len(values)
        rank = (n - 1) // 50 + 1 if n else None
        design = values[rank - 1] if n else None
        exceed = sum(1 for v in values if v > standard)
        if design is not None and design > standard:
            status = "nonattainment"
        elif n >= required:
            status = "attainment"
        else:
            status = "incomplete"
        row = {"site_id": s, "district": sites[s]["district"], "operator_class": sites[s]["operator_class"],
               "valid_days": n, "complete_days": complete[s], "exceedance_days": exceed,
               "design_rank": rank, "design_value": design, "status": status}
        audit_sites.append(row)
        per_site[s] = row

    def worst(members):
        best = None
        for s in members:
            v = per_site[s]["design_value"]
            if v is not None and (best is None or v > best[1]):
                best = (s, v)
        return {"site_id": best[0], "design_value": best[1]} if best else None

    out = {}
    rolled = 0
    for key, names, field in (("region", DISTRICTS, "district"), ("segment", CLASSES, "operator_class")):
        for name in names:
            members = [s for s in site_order if sites[s][field] == name]
            if not any(per_site[s]["status"] != "incomplete" for s in members):
                out[f"{key}_{name}.json"] = {field: name, "in_scope": False}
                continue
            total = sum(site_valid[s] for s in members)
            if key == "region":
                rolled += total
            out[f"{key}_{name}.json"] = {
                field: name,
                "in_scope": True,
                "sites": [{"site_id": s, "status": per_site[s]["status"], "valid_readings": site_valid[s],
                           "daily_values": {day_iso(d): v for d, v in sorted(daily[s].items())}} for s in members],
                "valid_readings": total,
                "exceedance_days": sum(per_site[s]["exceedance_days"] for s in members),
                "worst_site": worst(members),
                "status": "nonattainment" if any(per_site[s]["status"] == "nonattainment" for s in members) else "attainment",
            }
    top = worst(site_order)
    counts = {"attainment": 0, "incomplete": 0, "nonattainment": 0}
    for row in audit_sites:
        counts[row["status"]] += 1
    out["summary.json"] = {
        "report_id": man["report_id"],
        "first_day": man["first_day"],
        "days": days,
        "card_rows": len(ex["cards"]),
        "valid_readings": valid,
        "valid_hours": valid_hours,
        "valid_days": sum(r["valid_days"] for r in audit_sites),
        "exceedance_days": sum(r["exceedance_days"] for r in audit_sites),
        "site_status_counts": counts,
        "highest_design_value": {"site_id": top["site_id"], "value": top["design_value"]} if top else {"site_id": None, "value": None},
        "reconciliation": {"card_rows": len(ex["cards"]), "excluded_readings": excluded, "valid_readings": valid,
                           "rolled_up_valid_readings": rolled, "residual": valid - rolled},
    }
    out["policy_audit.json"] = {
        "policy_revision": pol["revision"],
        "span_register_revision": man["span_register_revision"],
        "daily_standard_tenths": standard,
        "hour_min_readings": hour_min,
        "day_min_hours": day_min,
        "required_valid_days": required,
        "sites": audit_sites,
    }
    out["data_quality.json"] = {
        "journal_entries": len(ex["journal"]),
        "excluded_readings": excluded,
        "exclusions": reasons,
        "units": unit_rows,
    }
    return {name: dump(out[name]) for name in REPORT_NAMES}


