SITE_WORDS = ("Harbour", "Mill", "Quarry", "Station", "Orchard", "Ferry", "Kiln", "Granary", "Tannery", "Foundry",
              "Market", "Wharf", "Chapel", "Bridge", "Forge", "Garrison", "Meadow", "Lock", "Rail", "Depot")
SITE_KINDS = ("Road", "Lane", "Yard", "Park", "Street", "Close", "Row", "Gate")
