PLATEAU = 700


class Rejected(Exception):
    pass


REJECTIONS = []


class World:
    pass


def _ceil15(value):
    return -((-value) // 15) * 15


def _offset_at(segs, k):
    o = segs[0][1]
    for start, off in segs:
        if start <= k:
            o = off
    return o


def _float_half_up(raw, factor_text):
    return int(raw * float(factor_text) + 0.5)


def _is_half(raw, factor_text):
    num, den = decimal_parts(factor_text)
    return (2 * raw * num) % (2 * den) == den


def _raw_for(value, factor):
    num, den = decimal_parts(factor)
    guess = value * den // num
    for raw in range(max(0, guess - 4), guess + 6):
        if half_up_product(raw, factor) == value:
            return raw
    return None


def _make_sites(rng, w, prof):
    n = len(prof["districts"])
    if prof.get("wide_ids"):
        pool = list(range(2, 33))
        rng.shuffle(pool)
        nums = sorted(pool[:n])
        if sum(1 for x in nums if x < 10) < 2 or sum(1 for x in nums if x >= 10) < 3:
            raise Rejected("site ids")
    else:
        nums = list(range(1, n + 1))
    used = set()
    w.sites = []
    for num, district in zip(nums, prof["districts"]):
        while True:
            name = f"{rng.choice(SITE_WORDS)} {rng.choice(SITE_KINDS)}"
            if name not in used:
                used.add(name)
                break
        w.sites.append({"site_id": f"S{num}", "site_name": name, "district": district,
                        "operator_class": prof["classes"][len(w.sites) % len(prof["classes"])]})


def _make_units(rng, w, prof):
    site_ids = [s["site_id"] for s in w.sites]
    n_units = sum(prof["channels"])
    swaps = prof.get("swaps", 0)
    if n_units != len(site_ids) + swaps:
        raise ValueError("profile unit count")
    nums = list(range(100, 1000))
    rng.shuffle(nums)
    w.units = [f"AQ{x}" for x in nums[:n_units]]
    w.chan = {}
    pos = 0
    for ci, count in enumerate(prof["channels"]):
        for _ in range(count):
            w.chan[w.units[pos]] = f"CH{ci + 1}"
            pos += 1
    order = list(w.units)
    rng.shuffle(order)
    primaries, spares = order[:len(site_ids)], order[len(site_ids):]
    w.spares = spares
    w.deploy = {u: [] for u in w.units}
    for site, unit in zip(site_ids, primaries):
        w.deploy[unit].append([site, w.w0 - rng.randint(1, 4) * 1440 - rng.randint(0, 600), None])
    taken = []
    for spare in spares:
        idx = rng.choice([i for i in range(len(site_ids)) if i not in taken])
        taken.append(idx)
        when = w.w0 + rng.randint(3, w.days - 4) * 1440 + rng.randint(0, 1439)
        old = primaries[idx]
        w.deploy[old][0][2] = when
        w.deploy[spare].append([site_ids[idx], when, None])
    w.span = {}
    for u in w.units:
        inst = min(d[1] for d in w.deploy[u])
        rem = w.deploy[u][-1][2]
        start = inst - rng.randint(60, 360)
        end = rem + rng.randint(45, 240) if rem is not None else w.w1 + rng.randint(120, 600)
        w.span[u] = (start, end)


def _make_clocks(rng, w, prof):
    w.residues = {}
    w.segs = {}
    for pos, u in enumerate(w.units):
        used = w.residues.setdefault(w.chan[u], set())
        if prof["hidden"] and pos == 0:
            # readings of this unit end exactly on the hour
            used.add(0)
            w.segs[u] = [(0, rng.choice((-15, 0, 15)))]
            continue
        if not prof["hidden"]:
            used.add(0)
        for _ in range(1000):
            o = rng.randint(-MAX_OFFSET, MAX_OFFSET)
            if (-o) % 15 not in used:
                break
        else:
            raise Rejected("residues")
        used.add((-o) % 15)
        w.segs[u] = [(0, o)]
    pool = [u for u in w.units if u not in w.spares and w.deploy[u][-1][2] is None]
    rng.shuffle(pool)
    w.echo_pairs = []
    busy = set()
    for _ in range(prof.get("echo", 0)):
        for a in pool:
            mates = [b for b in pool if b != a and a not in busy and b not in busy and w.chan[b] == w.chan[a]]
            if mates:
                w.echo_pairs.append((a, mates[0]))
                busy.update((a, mates[0]))
                break
        else:
            raise Rejected("echo pair")
    w.step_units = []
    rest = [u for u in w.units if u not in busy and u not in pool]
    rng.shuffle(rest)
    free = [u for u in pool if u not in busy] + rest
    for kind in prof.get("steps", ()):
        if not free:
            raise Rejected("step unit")
        w.step_units.append((free.pop(0), kind))


def _make_rows(rng, w):
    w.stamps = {}
    plan = dict(w.step_units)
    echoing = {x for pair in w.echo_pairs for x in pair}
    for u in w.units:
        start, end = w.span[u]
        outages = []
        for _ in range(0 if u in echoing else rng.randint(0, 2)):
            if end - start < 4 * 1440:
                break
            a = rng.randint(start + 1440, end - 1440)
            outages.append((a, a + rng.randint(4, 40) * 15))
        segs = w.segs[u]
        cuts = []
        if u in plan:
            kind = plan[u]
            lo = max(w.w0, min(d[1] for d in w.deploy[u])) + 2 * 1440
            hi = min(w.w1, w.deploy[u][-1][2] or w.w1) - 2 * 1440
            if hi - lo < 3 * 1440:
                raise Rejected("short step window")
            if kind == "one":
                cuts = [rng.randint(lo, hi)]
            else:
                a = rng.randint(lo, hi - 1440)
                cuts = [a, rng.randint(a + 720, hi)]
        base = cur = segs[0][1]
        stamp = _ceil15(start + cur)
        stamps = []
        while True:
            t = stamp - cur
            if t > end:
                break
            if cuts and t >= cuts[0]:
                cuts.pop(0)
                if plan.get(u) == "back" and len(segs) == 2:
                    new = base
                else:
                    used = w.residues[w.chan[u]]
                    options = [cur + d for d in range(-14, 15) if abs(d) >= 3 and -MAX_OFFSET <= cur + d <= MAX_OFFSET
                               and (-(cur + d)) % 15 not in used]
                    if not options:
                        raise Rejected("step offset")
                    new = rng.choice(options)
                    used.add((-new) % 15)
                if not new - cur < 15 or new == cur:
                    raise Rejected("bad step")
                segs.append((len(stamps), new))
                cur = new
                continue
            if not any(a <= t < b for a, b in outages):
                stamps.append(stamp)
            stamp += 15
        if cuts:
            raise Rejected("step not placed")
        w.stamps[u] = stamps
    _refresh_t(w)


def _refresh_t(w):
    w.t = {}
    for u in w.units:
        segs = w.segs[u]
        w.t[u] = [s - _offset_at(segs, k) for k, s in enumerate(w.stamps[u])]
        ts = w.t[u]
        if any(ts[i] >= ts[i + 1] for i in range(len(ts) - 1)):
            raise Rejected("time order")


def _make_echo(rng, w):
    w.f0 = {u: rng.randint(0, 255) for u in w.units}
    w.echo = []
    for a, b in w.echo_pairs:
        oa, ob = w.segs[a][0][1], w.segs[b][0][1]
        d = (ob - oa) % 15
        deltas = [d + m for m in (-30, -15, 0, 15, 30) if d + m != 0 and -MAX_OFFSET <= oa + d + m <= MAX_OFFSET]
        if not deltas:
            raise Rejected("echo delta")
        delta = rng.choice(deltas)
        n = len(w.t[a])
        k0 = n // 5 + rng.randint(0, n // 10)
        k1 = min(k0 + (n * 3) // 5, n - n // 8)
        # one card row of A is lost at each edge of the span, so the frame lockstep holds inside it only
        stamps = w.stamps[a]
        del stamps[k1]
        del stamps[k0 - 1]
        k0, k1 = k0 - 1, k1 - 1
        _refresh_t(w)
        tb = {t: j for j, t in enumerate(w.t[b])}
        ta = w.t[a]
        if any(ta[k] - delta not in tb for k in range(k0, k1)):
            raise Rejected("echo landing")
        j0 = tb[ta[k0] - delta]
        if any(tb[ta[k] - delta] - k != j0 - k0 for k in range(k0, k1)):
            raise Rejected("echo continuity")
        if any(ta[k] - ta[k - 1] != 15 for k in range(k0 + 1, k1)):
            raise Rejected("echo span gap")
        w.f0[a] = (w.f0[b] + j0 - k0) % 256
        w.echo.append({"a": a, "b": b, "delta": delta, "k0": k0, "k1": k1})
    w.frames = {u: [(w.f0[u] + k) % 256 for k in range(len(w.t[u]))] for u in w.units}


def _make_register(rng, w, prof):
    w.tags = []
    nums = list(range(100, 1000))
    rng.shuffle(nums)
    for i, u in enumerate(w.units):
        w.tags.append({"asset_tag": f"T-{nums[i]}", "unit_id": u, "valid_from_utc": to_iso(w.w0 - 90 * 1440),
                       "valid_to_utc": ""})
    factors = prof["factors"]
    reg = []
    counter = [0]

    def add(**kw):
        counter[0] += rng.randint(1, 3)
        row = {"revision": prof["revision"], "entry_id": f"E{counter[0]}", "unit_ref": "", "effective_utc": "",
               "span_factor": "", "action": "set", "target_entry": ""}
        row.update(kw)
        reg.append(row)
        return row

    def clear_instant(u, eff):
        ts = set(w.t[u])
        while eff in ts:
            eff += 1
        return eff

    tag_of = {t["unit_id"]: t["asset_tag"] for t in w.tags}
    for pos, u in enumerate(w.units):
        inst = min(d[1] for d in w.deploy[u])
        if u in w.spares and prof.get("late_calibration"):
            eff = clear_instant(u, inst + rng.randint(30, 240))
        else:
            eff = clear_instant(u, inst - rng.randint(60, 2880))
        ref = tag_of[u] if pos == 1 else u
        add(unit_ref=ref, effective_utc=to_iso(eff), span_factor=rng.choice(factors))
    for _ in range(prof.get("recalibrations", 1)):
        u = rng.choice(w.units)
        eff = clear_instant(u, w.w0 + rng.randint(2, w.days - 3) * 1440 + rng.randint(0, 1439))
        add(unit_ref=u, effective_utc=to_iso(eff), span_factor=rng.choice(factors))
    if prof.get("errata"):
        sets = [r for r in reg if r["action"] == "set"]
        target = rng.choice(sets)
        low = add(action="amend", span_factor=rng.choice(factors), target_entry=target["entry_id"])
        high = add(action="amend", span_factor=rng.choice(factors), target_entry=target["entry_id"])
        while high["span_factor"] == low["span_factor"]:
            high["span_factor"] = rng.choice(factors)
        # the governing (higher-numbered) amendment is listed first
        reg[-1], reg[-2] = reg[-2], reg[-1]
        add(action="amend", span_factor=rng.choice(factors), target_entry=low["entry_id"])
        am = add(action="amend", span_factor=rng.choice(factors), target_entry=rng.choice(sets)["entry_id"])
        wd = add(action="withdraw", target_entry=am["entry_id"])
        add(action="withdraw", target_entry=wd["entry_id"])
        add(action="withdraw", target_entry=f"E{counter[0] + 41}")
        u = rng.choice(w.units)
        extra = add(unit_ref=u, effective_utc=to_iso(w.w0 + rng.randint(2, w.days - 3) * 1440 + rng.randint(0, 1439)),
                    span_factor=rng.choice(factors))
        add(action="withdraw", target_entry=extra["entry_id"])
    if prof.get("alias"):
        a, c = w.units[0], w.units[1]
        move = w.w0 + rng.randint(3, w.days - 4) * 1440 + rng.randint(0, 1439)
        tag = w.tags[0]["asset_tag"]
        w.tags[0]["valid_to_utc"] = to_iso(move)
        w.tags.append({"asset_tag": tag, "unit_id": c, "valid_from_utc": to_iso(move), "valid_to_utc": ""})
        late_tag = f"T-{nums[len(w.units) + 1]}"
        start = w.w0 + rng.randint(5, w.days - 2) * 1440
        w.tags.append({"asset_tag": late_tag, "unit_id": a, "valid_from_utc": to_iso(start), "valid_to_utc": ""})
        add(unit_ref=tag, effective_utc=to_iso(move + rng.randint(60, 1440)), span_factor=rng.choice(factors))
        add(unit_ref=late_tag, effective_utc=to_iso(start - rng.randint(60, 1440)), span_factor=rng.choice(factors))
    if prof.get("tie_effective"):
        u = rng.choice(w.units)
        eff = w.w0 + rng.randint(2, w.days - 3) * 1440 + rng.randint(0, 1439)
        first = add(unit_ref=u, effective_utc=to_iso(eff), span_factor=rng.choice(factors))
        second = add(unit_ref=u, effective_utc=to_iso(eff), span_factor=rng.choice(factors))
        while second["span_factor"] == first["span_factor"]:
            second["span_factor"] = rng.choice(factors)
        # the governing (higher-numbered) entry is listed first
        reg[-1], reg[-2] = reg[-2], reg[-1]
    for _ in range(prof.get("inclusive_effective", 0)):
        u = rng.choice(w.units)
        ts = [t for t in w.t[u] if w.w0 + 1440 < t < w.w1 - 1440 and t % 60 == (-w.std) % 60]
        if not ts:
            ts = [t for t in w.t[u] if w.w0 + 1440 < t < w.w1 - 1440]
        add(unit_ref=u, effective_utc=to_iso(rng.choice(ts)), span_factor=rng.choice(factors))
    w.register = reg
    w.table = span_table(reg, w.tags)


def _make_maintenance(rng, w, prof):
    w.maint = []
    site_ids = [s["site_id"] for s in w.sites]
    for s in site_ids:
        for _ in range(rng.randint(1, 3)):
            b = w.w0 + rng.randint(0, w.days - 1) * 1440 + rng.randint(0, 1380)
            w.maint.append([s, b, b + rng.randint(2, 10) * 15])
    if prof.get("dark_site"):
        lone = [s["site_id"] for s in w.sites
                if sum(1 for x in w.sites if x["district"] == s["district"]) == 1 and s["district"] in DISTRICTS]
        if not lone:
            raise ValueError("profile dark site")
        w.maint.append([lone[0], w.w0 + 2 * 1440, w.w1 - 2 * 1440])
        w.dark = lone[0]
    if prof.get("dst_maintenance"):
        site_ids_ = [s["site_id"] for s in w.sites]
        for begins_lst, ends_dst, shift in prof["dst"]:
            b_utc = to_min(begins_lst) - w.std
            e_utc = to_min(ends_dst) - w.std - shift
            if w.w0 + 120 < b_utc < w.w1 - 120:
                w.maint.append([rng.choice(site_ids_), b_utc - 55, b_utc - 5])
            if w.w0 + 120 < e_utc < w.w1 - 240:
                w.maint.append([rng.choice(site_ids_), e_utc + shift + 5, e_utc + shift + 50])
    for _ in range(prof.get("dst_maintenance", 0)):
        spans = []
        for begins_lst, ends_dst, shift in prof["dst"]:
            begins = to_min(begins_lst) - w.std
            ends = to_min(ends_dst) - w.std - shift
            lo, hi = max(w.w0, begins + 1440), min(w.w1, ends) - 1440
            if hi > lo:
                spans.append((lo, hi))
        if not spans:
            raise ValueError("profile dst window")
        lo, hi = spans[0]
        b = rng.randint(lo, hi)
        w.maint.append([rng.choice(site_ids), b, b + rng.randint(4, 10) * 15])


def _civil_unclear(utc, zone_std, dst):
    # a civil time inside an hour that civil time skips or repeats
    zone = {"standard_offset_minutes": zone_std,
            "daylight_saving": [{"begins": b, "ends": e, "shift_minutes": sh} for b, e, sh in dst]}
    civil = _utc_to_civil(utc, zone)
    for begins_lst, ends_dst, shift in dst:
        if to_min(begins_lst) <= civil < to_min(begins_lst) + shift:
            return True
        if to_min(ends_dst) - shift <= civil < to_min(ends_dst):
            return True
    return False


def _site_at(w, u, t):
    for s, inst, rem in w.deploy[u]:
        if inst <= t and (rem is None or t < rem):
            return s
    return None


def _make_readings(rng, w):
    level = {}
    episode = w.prof.get("episode_den", 7)
    for s in w.sites:
        for d in range(w.first - 7, w.first + w.days + 7):
            base = rng.randint(70, 300)
            if rng.chance(1, episode):
                base = rng.randint(330, 520)
            level[(s["site_id"], d)] = base
    w.rec = {}
    for u in w.units:
        recs = []
        run, code = 0, ""
        for k, t in enumerate(w.t[u]):
            site = _site_at(w, u, t)
            hour = (t + w.std - 1) // 60
            day = hour // 24
            if site is not None:
                diurnal = 80 + (30 if hour % 24 in (7, 8, 9, 17, 18, 19) else 0) + rng.randint(0, 25)
                value = level[(site, day)] * diurnal // 100 + rng.randint(-12, 12)
            else:
                value = rng.randint(15, 70)
            if run:
                run -= 1
            elif rng.chance(1, 170):
                code = rng.choice(("Z", "S", "F"))
                run = {"Z": 2, "S": 3, "F": rng.randint(1, 6)}[code]
            recs.append({"k": k, "t": t, "site": site, "hour": hour, "day": day, "value": max(5, value),
                         "status": code if run else "", "missing": rng.chance(1, 260), "planted": False})
        w.rec[u] = recs


def _valid(w, u, r):
    if not w.first <= r["day"] < w.first + w.days:
        return False
    if r["site"] is None or r["missing"] or r["status"]:
        return False
    if factor_at(w.table, u, r["t"]) is None:
        return False
    return not any(s == r["site"] and b <= r["t"] < e for s, b, e in w.maint)


def _site_day_hours(w, site, day):
    if not hasattr(w, "sd_index"):
        w.sd_index = {}
        for u in w.units:
            for r in w.rec[u]:
                if r["site"] is not None:
                    w.sd_index.setdefault((r["site"], r["day"]), []).append((u, r))
    hours = {}
    for u, r in w.sd_index.get((site, day), ()):
        if _valid(w, u, r):
            hours.setdefault(r["hour"], []).append((u, r))
    return hours


def _set_hour(w, members, target):
    # values summing to len(members) * target, every one attainable under its factor
    n = len(members)
    values = [target] * n
    for i in range(0, n - 1, 2):
        d = (i // 2 + 1) * 3
        values[i] += d
        values[i + 1] -= d
    for (u, r), v in zip(members, values):
        factor = factor_at(w.table, u, r["t"])
        if _raw_for(v, factor) is None:
            return False
    for (u, r), v in zip(members, values):
        r["value"] = v
        r["planted"] = True
    return True


def _plant_day(w, site, day, target, max_hours=None):
    hours = _site_day_hours(w, site, day)
    good = {h: m for h, m in hours.items() if len(m) >= w.hour_min}
    if max_hours is None and len(good) < w.day_min:
        return False
    if max_hours is not None and not 1 <= len(good) <= max_hours:
        return False
    if any(r["planted"] for m in hours.values() for _, r in m):
        return False
    for h, members in hours.items():
        if not _set_hour(w, members, target):
            return False
    return True


def _plant(rng, w, prof):
    std_t = tenths(prof["policy"]["daily_standard"])
    w.hour_min = prof["policy"]["hour_min_readings"]
    w.day_min = prof["policy"]["day_min_hours"]
    site_ids = [s["site_id"] for s in w.sites]
    days = list(range(w.first + 1, w.first + w.days - 1))
    w.plants = {"limit": [], "exception": [], "tie": [], "half": 0}
    # on-limit complete days
    targets = prof["limit_targets"]
    tries = 0
    while len(w.plants["limit"]) < len(targets) and tries < 400:
        tries += 1
        s, d = rng.choice(site_ids), rng.choice(days)
        if _plant_day(w, s, d, targets[len(w.plants["limit"])]):
            w.plants["limit"].append((s, d))
    if len(w.plants["limit"]) < len(targets):
        raise Rejected("limit plants")
    # incomplete days: a long maintenance window leaves fewer valid hours than the day minimum
    for value in prof.get("exception_targets", ()):
        for _ in range(200):
            s, d = rng.choice(site_ids), rng.choice(days)
            begin = d * 1440 - w.std + rng.randint(5, 7) * 60
            w.maint.append([s, begin, begin + rng.randint(9, 11) * 60])
            if _plant_day(w, s, d, value, max_hours=w.day_min - 1):
                w.plants["exception"].append((s, d, value))
                break
            w.maint.pop()
        else:
            raise Rejected("exception plant")
    # worst-site tie inside one district at a plateau no natural day reaches
    if prof.get("tie"):
        by_district = {}
        for s in w.sites:
            if s["district"] in DISTRICTS:
                by_district.setdefault(s["district"], []).append(s["site_id"])
        pairs = [m for m in by_district.values() if len(m) >= 2]
        if not pairs:
            raise Rejected("tie district")
        mixed = [m for m in pairs if any(site_number(x) < 10 for x in m) and any(site_number(x) >= 10 for x in m)]
        if prof.get("wide_ids") and mixed:
            members = rng.choice(mixed)
            pair = [min((x for x in members if site_number(x) >= 10), key=site_number),
                    rng.choice([x for x in members if site_number(x) < 10])]
        else:
            members = rng.choice(pairs)
            pair = sorted(members, key=site_number)[:2]
        need = 2 if w.days >= 51 else 1
        for s in pair:
            got = 0
            for _ in range(300):
                d = rng.choice(days)
                if _plant_day(w, s, d, PLATEAU):
                    got += 1
                    if got == need:
                        break
            if got < need:
                raise Rejected("tie plant")
        w.plants["tie"] = pair


def _make_raw(rng, w, prof):
    half_goal = prof.get("half_rows", 0)
    if prof["hidden"] and not half_goal:
        half_goal = sum(len(w.t[u]) for u in w.units) // 400 + 12
    for u in w.units:
        for r in w.rec[u]:
            factor = factor_at(w.table, u, r["t"])
            if factor is None:
                r["raw"] = r["value"]
                continue
            raw = _raw_for(r["value"], factor)
            while raw is None:
                r["value"] += 1
                raw = _raw_for(r["value"], factor)
            r["raw"] = raw
    rows = [(u, r) for u in w.units for r in w.rec[u] if _valid(w, u, r) and not r["planted"]]
    if half_goal:
        rng.shuffle(rows)
        planted = 0
        for u, r in rows:
            if planted >= half_goal:
                break
            factor = factor_at(w.table, u, r["t"])
            for raw in range(max(1, r["raw"] - 30), r["raw"] + 30):
                if _is_half(raw, factor) and _float_half_up(raw, factor) != half_up_product(raw, factor):
                    r["raw"] = raw
                    r["half"] = True
                    planted += 1
                    break
        if planted < half_goal:
            raise Rejected("half rows")
        w.plants["half"] = planted
    else:
        for u in w.units:
            for r in w.rec[u]:
                factor = factor_at(w.table, u, r["t"])
                if factor is None:
                    continue
                if r["planted"] and _is_half(r["raw"], factor):
                    raise Rejected("planted half")
                while _is_half(r["raw"], factor) or _float_half_up(r["raw"], factor) != half_up_product(r["raw"], factor):
                    r["raw"] += 1


def _site_days(w, site):
    """LST day -> value for one site, following the stated daily rule."""
    hours = {}
    for u, r in [(u, r) for u in w.units for r in w.rec[u] if r["site"] == site]:
        if _valid(w, u, r):
            cell = hours.setdefault(r["hour"], [0, 0])
            cell[0] += half_up_product(r["raw"], factor_at(w.table, u, r["t"]))
            cell[1] += 1
    per_day = {}
    for hour, (total, count) in hours.items():
        if count >= w.hour_min:
            cell = per_day.setdefault(hour // 24, [0, 0])
            cell[0] += total // count
            cell[1] += 1
    std_t = tenths(w.prof["policy"]["daily_standard"])
    out = {}
    for day, (total, count) in per_day.items():
        mean = total // count
        if count >= w.day_min or mean > std_t:
            out[day] = mean
    return out


def _plant_fifty(rng, w, prof):
    if not prof.get("fifty"):
        return
    skip = set(w.plants["tie"]) | {s for s, _ in w.plants["limit"]} | {s for s, _, _ in w.plants["exception"]}
    options = [s["site_id"] for s in w.sites if s["site_id"] not in skip and s["district"] in DISTRICTS]
    rng.shuffle(options)
    for site in options:
        days = _site_days(w, site)
        if len(days) < 52:
            continue
        top = sorted(days.values(), reverse=True)
        if top[0] == top[1]:
            continue
        keep_top = {d for d, v in days.items() if v == top[0] or v == top[1]}
        removable = [d for d in sorted(days) if d not in keep_top]
        rng.shuffle(removable)
        for d in removable[:len(days) - 50]:
            b = d * 1440 - w.std
            w.maint.append([site, b, b + 1440])
        if len(_site_days(w, site)) != 50:
            raise Rejected("fifty")
        w.plants["fifty"] = site
        return
    raise Rejected("fifty site")


def _make_journal(rng, w, prof):
    rate = {u: rng.randint(prof.get("rate_lo", 72), prof.get("rate_hi", 95)) for u in w.units}
    forced = {u: set() for u in w.units}
    for u, kind in w.step_units:
        for start, _ in w.segs[u][1:]:
            forced[u].update((start - 1, start))
    for e in w.echo:
        rate[e["a"]] = rng.randint(22, 32)
        rate[e["b"]] = rng.randint(88, 96)
    w.rate = rate
    w.heard = {}
    for u in w.units:
        for k, t in enumerate(w.t[u]):
            if k in forced[u] or rng.chance(rate[u], 100):
                key = (w.chan[u], t)
                if key in w.heard:
                    raise Rejected("channel collision")
                w.heard[key] = (w.frames[u][k], u, k)


def candidates(w):
    """receipt key -> list of (unit, k, offset) whose frame matches within the offset domain."""
    index = {}
    for u in w.units:
        for k, s in enumerate(w.stamps[u]):
            f = w.frames[u][k]
            for o in range(-MAX_OFFSET, MAX_OFFSET + 1):
                key = (w.chan[u], s - o)
                got = w.heard.get(key)
                if got is not None and got[0] == f:
                    index.setdefault(key, []).append((u, k, o))
    return index


def _check(w, prof):
    cand = candidates(w)
    # every step is bracketed by two received rows that only one reading explains
    for u, kind in w.step_units:
        for start, _ in w.segs[u][1:]:
            for k in (start - 1, start):
                key = (w.chan[u], w.t[u][k])
                if len(cand.get(key, ())) != 1:
                    raise Rejected("bracket ambiguous")
    # per-unit count-match picks the echo offset for A
    w.countmatch_wrong = 0
    for e in w.echo:
        votes = {}
        for key, lst in cand.items():
            for u, k, o in lst:
                if u == e["a"]:
                    votes[o] = votes.get(o, 0) + 1
        best = max(sorted(votes), key=lambda o: votes[o])
        if best == w.segs[e["a"]][0][1]:
            raise Rejected("count-match not fooled")
        w.countmatch_wrong += 1
    # each segment of each unit carries at least three single-candidate receipts
    single = {}
    for key, lst in cand.items():
        if len(lst) == 1:
            u, k, o = lst[0]
            single.setdefault(u, []).append(k)
    for u in w.units:
        segs = w.segs[u] + [(len(w.t[u]), None)]
        ks = single.get(u, [])
        for (a, _), (b, _) in zip(segs, segs[1:]):
            if sum(1 for k in ks if a <= k < b) < 3:
                raise Rejected("thin segment")
    for s_, b, e in w.maint:
        if _civil_unclear(b, w.std, prof["dst"]) or _civil_unclear(e, w.std, prof["dst"]):
            raise Rejected("maintenance near a clock change")
    w.cand = cand


def _variant_label(rng, label, on):
    if not on:
        return label
    return rng.choice((label, label.lower(), " " + label, label + " ", label.title(), " " + label.lower()))


def _write(rng, w, prof):
    files = {}

    def csv_text(header, rows, bom=False):
        buf = io.StringIO()
        wr = csv.writer(buf, lineterminator="\n")
        wr.writerow(header)
        for row in rows:
            wr.writerow(row)
        return ("﻿" if bom else "") + buf.getvalue()

    files["site_register.csv"] = csv_text(["site_id", "site_name", "district", "operator_class"],
                                          [[s["site_id"], s["site_name"], s["district"], s["operator_class"]]
                                           for s in w.sites], bom=True)
    dep_rows = []
    for u in sorted(w.units):
        for s, inst, rem in w.deploy[u]:
            dep_rows.append([u, s, _variant_label(rng, w.chan[u], prof.get("labels")), to_iso(inst),
                             to_iso(rem) if rem is not None else ""])
    files["unit_deployments.csv"] = csv_text(["unit_id", "site_id", "channel", "installed_utc", "removed_utc"], dep_rows)
    files["asset_tags.csv"] = csv_text(["asset_tag", "unit_id", "valid_from_utc", "valid_to_utc"],
                                       [[t["asset_tag"], t["unit_id"], t["valid_from_utc"], t["valid_to_utc"]]
                                        for t in sorted(w.tags, key=lambda x: (x["asset_tag"], x["valid_from_utc"]))])
    card = []
    flags = []
    for u in sorted(w.units):
        for r in w.rec[u]:
            card.append([u, to_iso(w.stamps[u][r["k"]]), w.frames[u][r["k"]],
                         "" if r["missing"] else r["raw"], r["status"]])
            flags.append(bool(r.get("half")))
    if prof.get("shuffle_cards"):
        order = list(range(len(card)))
        rng.shuffle(order)
        card = [card[i] for i in order]
        flags = [flags[i] for i in order]
        # spread the exact-half rows so every 500-row band of the file holds some
        halves = [i for i, f in enumerate(flags) if f]
        others = [i for i, f in enumerate(flags) if not f]
        if halves:
            step = len(card) / len(halves)
            targets = sorted({min(len(card) - 1, int(step * j + step / 2)) for j in range(len(halves))})
            placed = [None] * len(card)
            mark = [False] * len(card)
            for t, h in zip(targets, halves):
                placed[t] = card[h]
                mark[t] = True
            rest = iter(card[i] for i in others + halves[len(targets):])
            card = [row if row is not None else next(rest) for row in placed]
            if any(not any(mark[b:b + 500]) for b in range(0, len(card), 500)):
                raise Rejected("half rows not spread")
    files["card_readings.csv"] = csv_text(["unit_id", "card_stamp", "frame", "pm25_raw", "status"], card)
    journal = [[_variant_label(rng, ch, prof.get("labels")), to_iso(t), f]
               for (ch, t), (f, _, _) in sorted(w.heard.items())]
    rng.shuffle(journal)
    files["receipt_journal.csv"] = csv_text(["channel", "received_utc", "frame"], journal)
    reg_header = ["revision", "entry_id", "unit_ref", "effective_utc", "span_factor", "action", "target_entry"]
    true_reg = [[r[h] for h in reg_header] for r in w.register]
    stale = []
    for r in w.register[:-2] if len(w.register) > 4 else w.register:
        row = [r[h] for h in reg_header]
        row[0] = prof["stale_revision"]
        if row[5] == "set" and rng.chance(1, 2):
            row[4] = rng.choice(prof["factors"])
        stale.append(row)
    names = ("span_register.csv", "span_register_final.csv")
    if prof.get("swap_register"):
        names = names[::-1]
    files[names[0]] = csv_text(reg_header, true_reg)
    files[names[1]] = csv_text(reg_header, stale)
    policy = dict(prof["policy"])
    policy["revision"] = prof["policy_revision"]
    stale_policy = dict(prof["stale_policy"])
    stale_policy["revision"] = prof["stale_policy_revision"]
    pnames = ("network_policy.json", "network_policy_v2.json")
    if prof.get("swap_policy"):
        pnames = pnames[::-1]
    files[pnames[0]] = dump(policy)
    files[pnames[1]] = dump(stale_policy)
    basis = prof.get("time_basis", "civil")
    zone = {"standard_offset_minutes": w.std,
            "daylight_saving": [{"begins": b, "ends": e, "shift_minutes": sh} for b, e, sh in prof["dst"]]}
    entries = []
    for s, b, e in sorted(w.maint, key=lambda m: (m[1], site_number(m[0]))):
        if basis == "civil":
            bt, et = _utc_to_civil(b, zone), _utc_to_civil(e, zone)
        else:
            bt, et = b, e
        entries.append({"site_id": s, "begins": to_iso(bt), "ends": to_iso(et), "work": rng.choice(WORK)})
    files["maintenance_log.json"] = dump({"time_basis": basis, "entries": entries})
    files["zone_rules.json"] = dump(zone)
    files["extract_manifest.json"] = dump({
        "network": prof["network"],
        "report_id": prof["report_id"],
        "first_day": day_iso(w.first),
        "days": w.days,
        "span_register_revision": prof["revision"],
        "policy_revision": prof["policy_revision"],
    })
    w.files = files


def _bands_ok(w, prof):
    """Every 500-row band of the receipt journal holds an echo-ambiguous entry and a relabelled channel."""
    text = w.files["receipt_journal.csv"].splitlines()[1:]
    ambiguous = {key for key, lst in w.cand.items() if len(lst) > 1}
    for b in range(0, len(text), 500):
        band = [line.split(",") for line in text[b:b + 500]]
        if not any((canon_channel(ch), to_min(t)) in ambiguous for ch, t, _ in band):
            return False
        if prof.get("labels") and not any(ch != canon_channel(ch) for ch, _, _ in band):
            return False
    return True


def _utc_to_civil(utc, zone):
    std = zone["standard_offset_minutes"]
    for p in zone["daylight_saving"]:
        begins = to_min(p["begins"]) - std
        ends = to_min(p["ends"]) - std - p["shift_minutes"]
        if begins <= utc < ends:
            return utc + std + p["shift_minutes"]
    return utc + std


def truth_offsets(w):
    return {u: list(w.segs[u]) for u in w.units}


def build_world(seed, prof):
    for attempt in range(60):
        rng = Rng(seed * 1000003 + attempt * 7919 + 17)
        w = World()
        w.prof = prof
        w.std = prof["std_off"]
        w.days = prof["days"]
        w.first = day_index(prof["first_day"])
        w.w0 = w.first * 1440 - w.std
        w.w1 = w.w0 + w.days * 1440
        try:
            _make_sites(rng, w, prof)
            _make_units(rng, w, prof)
            _make_clocks(rng, w, prof)
            _make_rows(rng, w)
            _make_echo(rng, w)
            _make_register(rng, w, prof)
            _make_maintenance(rng, w, prof)
            _make_readings(rng, w)
            _plant(rng, w, prof)
            _make_raw(rng, w, prof)
            _plant_fifty(rng, w, prof)
            _make_journal(rng, w, prof)
            _check(w, prof)
            _write(rng, w, prof)
            if prof["hidden"] and not _bands_ok(w, prof):
                raise Rejected("journal bands")
        except Rejected as exc:
            REJECTIONS.append(str(exc))
            continue
        w.attempt = attempt
        return w
    raise RuntimeError(f"no world for seed {seed}")


def write_extract(w, root):
    root = Path(root)
    root.mkdir(parents=True, exist_ok=True)
    for name, text in w.files.items():
        (root / name).write_bytes(text.encode("utf-8"))
    return root


