# ---------------------------------------------------------------- running the delivered program

PROGRAM = Path("/app/out/derive_report.py")
SUBMITTED = Path("/app/out")
CALL_LIMIT = 60
_SETPRIV = ["setpriv", "--reuid=nobody", "--regid=nogroup", "--clear-groups"]
_FORBIDDEN_ROOTS = ("/tests", "/logs", "/solution", "/root", "/home", "/app")
_WRITE_FLAGS = os.O_WRONLY | os.O_RDWR | os.O_CREAT | os.O_APPEND | os.O_TRUNC
_COMMON_NUMBERS = {100, 255, 256, 1000, 1440, 3600, 2026, 2027, 10000}
_LOCK = threading.RLock()
_CACHE = {}

_WRAPPER = r'''
import json, os, runpy, sys
_log = open(sys.argv[1], "a", buffering=1)
_dumps, _fsdecode, _write = json.dumps, os.fsdecode, _log.write
def _hook(event, args):
    try:
        if event == "open":
            path, mode, flags = (list(args) + [None, None, None])[:3]
            if isinstance(path, int):
                return
            _write(_dumps(["open", _fsdecode(path), mode if isinstance(mode, str) else "",
                           flags if isinstance(flags, int) else 0]) + "\n")
        elif event in ("os.listdir", "os.scandir"):
            path = args[0] if args else None
            if not isinstance(path, int):
                _write(_dumps(["list", _fsdecode(path) if path is not None else ".", "", 0]) + "\n")
        elif event in ("socket.connect", "socket.bind", "socket.getaddrinfo"):
            _write(_dumps(["net", event, "", 0]) + "\n")
    except Exception:
        pass
sys.addaudithook(_hook)
_program = sys.argv[2]
sys.argv = [_program] + sys.argv[3:]
sys.path[0] = os.path.dirname(_program)
runpy.run_path(_program, run_name="__main__")
'''


def _seal(root):
    for path in root.rglob("*"):
        path.chmod(0o755 if path.is_dir() else 0o644)
    root.chmod(0o755)


def _shipped_root():
    with _LOCK:
        if "shipped_root" not in _CACHE:
            root = Path(tempfile.mkdtemp(prefix="pnca-shipped-"))
            for rel, blob in _SHIPPED_DATA.items():
                (root / rel).write_bytes(zlib.decompress(base64.b64decode(blob)))
            _seal(root)
            _CACHE["shipped_root"] = root
        return _CACHE["shipped_root"]


def _shipped_expected():
    with _LOCK:
        if "shipped_expected" not in _CACHE:
            try:
                _CACHE["shipped_expected"] = reference_reports(_shipped_root())
            except Exception:
                _CACHE["shipped_expected"] = None
        return _CACHE["shipped_expected"]


def _tree_digest(root):
    digest = hashlib.sha256()
    for path in sorted(root.rglob("*")):
        digest.update(str(path.relative_to(root)).encode())
        if path.is_file():
            digest.update(path.read_bytes())
    return digest.hexdigest()


def _kill_untrusted():
    try:
        nobody = pwd.getpwnam("nobody").pw_uid
    except KeyError:
        return
    for entry in Path("/proc").iterdir():
        if not entry.name.isdigit():
            continue
        try:
            status = (entry / "status").read_text()
        except OSError:
            continue
        for line in status.splitlines():
            if line.startswith("Uid:") and int(line.split()[1]) == nobody:
                try:
                    os.kill(int(entry.name), signal.SIGKILL)
                except OSError:
                    pass


def _give_to_runner(*paths):
    if os.geteuid() == 0:
        nobody = pwd.getpwnam("nobody")
        for path in paths:
            os.chown(path, nobody.pw_uid, nobody.pw_gid)


def _prepare(data_root, label, where=None):
    """A private copy of one extract, a staged copy of the program and an empty output directory."""
    base = Path(where) if where else Path(tempfile.mkdtemp(prefix=f"pnca-run-{label}-"))
    base.mkdir(parents=True, exist_ok=True)
    data = base / "data"
    shutil.copytree(data_root, data)
    stage = base / "program"
    stage.mkdir()
    shutil.copyfile(PROGRAM, stage / "derive_report.py")
    (stage / "audit_wrapper.py").write_text(_WRAPPER, encoding="utf-8")
    _seal(base)
    out = base / "out"
    work = base / "cwd"
    out.mkdir()
    work.mkdir()
    _give_to_runner(out, work)
    return {"base": base, "data": data, "stage": stage, "out": out, "cwd": work}


def _execute(place, log_name):
    """Run the staged program once as the unprivileged user; returns a result dict."""
    log = place["base"] / log_name
    log.touch()
    _give_to_runner(log)
    log.chmod(0o600)
    command = [sys.executable, "-B", str(place["stage"] / "audit_wrapper.py"), str(log),
               str(place["stage"] / "derive_report.py"), str(place["data"]), str(place["out"])]
    if os.geteuid() == 0:
        command = [*_SETPRIV, *command]
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "PYTHONDONTWRITEBYTECODE": "1", "LANG": "C.UTF-8",
           "HOME": str(place["cwd"])}
    before = _tree_digest(place["data"])
    result = {"ok": False, "stdout": "", "files": {}, "events": [], "elapsed": None, "modified": False,
              "data_dir": str(place["data"]), "out_dir": str(place["out"]), "stage": str(place["stage"]),
              "cwd": str(place["cwd"])}
    proc = None
    started = time.monotonic()
    try:
        proc = subprocess.Popen(command, cwd=str(place["cwd"]), env=env, stdout=subprocess.PIPE,
                                stderr=subprocess.DEVNULL, start_new_session=True)
        stdout, _ = proc.communicate(timeout=CALL_LIMIT)
        result["elapsed"] = time.monotonic() - started
        result["stdout"] = stdout.decode("utf-8", "replace")
        result["ok"] = proc.returncode == 0
    except subprocess.TimeoutExpired:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except OSError:
            pass
        _kill_untrusted()
        try:
            proc.communicate(timeout=10)
        except (subprocess.TimeoutExpired, OSError, ValueError):
            pass
    except OSError:
        pass
    finally:
        _kill_untrusted()
    for name in REPORT_NAMES:
        path = place["out"] / name
        if path.is_file():
            result["files"][name] = path.read_bytes()
    try:
        for line in log.read_text(encoding="utf-8", errors="replace").splitlines():
            try:
                result["events"].append(json.loads(line))
            except ValueError:
                continue
    except OSError:
        pass
    result["modified"] = _tree_digest(place["data"]) != before
    return result


def _cached(key, factory):
    with _LOCK:
        if key not in _CACHE:
            try:
                _CACHE[key] = factory()
            except Exception:
                _CACHE[key] = None
        return _CACHE[key]


def _shipped_place():
    return _cached("shipped_place", lambda: _prepare(_shipped_root(), "a"))


def _shipped_first():
    return _cached("shipped_first", lambda: _execute(_shipped_place(), "audit-first.log"))


def _shipped_again():
    def factory():
        place = _shipped_place()
        _shipped_first()
        for path in place["out"].iterdir():
            path.unlink()
        return _execute(place, "audit-again.log")
    return _cached("shipped_again", factory)


def _shipped_elsewhere():
    def factory():
        where = Path(tempfile.mkdtemp(prefix="pnca-elsewhere-")) / "nested dir" / "second copy"
        place = _prepare(_shipped_root(), "b", where=where)
        _seal(where.parent.parent)
        return _execute(place, "audit-elsewhere.log")
    return _cached("shipped_elsewhere", factory)


def _hidden_case(index):
    def factory():
        world = build_world(EVAL_SEED + index, HIDDEN_PROFILES[index])
        root = write_extract(world, Path(tempfile.mkdtemp(prefix=f"pnca-held-{index:02d}-")) / "extract")
        expected = reference_reports(root, truth_offsets(world))
        return {"expected": expected, "result": _execute(_prepare(root, f"h{index:02d}"), "audit.log")}
    return _cached(("hidden", index), factory)


def _hidden_passes(index):
    case = _hidden_case(index)
    if not case or not case["result"]["ok"]:
        return False
    files = case["result"]["files"]
    return all(files.get(name) == case["expected"][name].encode("utf-8") for name in REPORT_NAMES)


def _shipped_matches(name):
    expected = _shipped_expected()
    try:
        return expected is not None and (SUBMITTED / name).read_bytes() == expected[name].encode("utf-8")
    except OSError:
        return False


def _runs():
    runs = [_shipped_first(), _shipped_again(), _shipped_elsewhere()]
    runs += [case["result"] for case in (_hidden_case(i) for i in range(len(HIDDEN_PROFILES))) if case]
    return [run for run in runs if run]


def _program_tree():
    try:
        return ast.parse(PROGRAM.read_text(encoding="utf-8", errors="replace"))
    except (OSError, SyntaxError, ValueError):
        return None


def _inside(path, root):
    return path == root or path.startswith(root.rstrip("/") + "/")


def _resolved(path, run):
    if not path.startswith("/"):
        path = os.path.normpath(os.path.join(run["cwd"], path))
    return os.path.normpath(path)


def _documented_numbers():
    numbers = set()
    for rel, blob in _SHIPPED_DATA.items():
        if rel.endswith(".md"):
            text = zlib.decompress(base64.b64decode(blob)).decode("utf-8")
            numbers.update(int(tok) for tok in re.findall(r"(?<![\w.])\d+(?![\w.])", text))
    return numbers


def _report_numbers():
    numbers = set()

    def walk(value):
        if isinstance(value, bool):
            return
        if isinstance(value, int):
            numbers.add(value)
        elif isinstance(value, dict):
            for item in value.values():
                walk(item)
        elif isinstance(value, list):
            for item in value:
                walk(item)

    for text in (_shipped_expected() or {}).values():
        walk(json.loads(text))
    return numbers


def _hit(fn):
    try:
        return bool(fn())
    except Exception:
        return False


