def _write_corpus(root: Path) -> None:
    """Write every held-out extract, and one challenge extract in the shipped profile, under root."""
    root = Path(root)
    for index, profile in enumerate(HIDDEN_PROFILES):
        write_extract(build_world(EVAL_SEED + index, profile), root / f"held_out_{index + 1:02d}")
    write_extract(build_world(CHALLENGE_SEED, SHIPPED_PROFILE), root / "challenge")


if __name__ == "__main__":
    _write_corpus(Path(sys.argv[1]))


